  test('a computer on this wifi signed into another account is said, not waited on', async () => {
    /*
     * "The issue it wasn't connecting is because I was signed into the wrong
     * account, but it didn't notify me at all… Please be clear which account
     * needs to be trying to sign into, or which one it is signing into, and
     * they don't match somehow."
     */
    const sql = read('supabase/migrations/20260923_computer_elsewhere.sql')
    assert.match(sql, /returns boolean/, 'the account server says more than yes or no about another account')
    assert.ok(!/auth\.users/.test(sql), 'the check reads other accounts’ details, which it has no need of')
    assert.match(sql, /grant execute on function public\.computer_elsewhere\(\) to authenticated/, 'a signed-in phone cannot ask')
    assert.match(sql, /revoke all on function public\.computer_elsewhere\(\) from public, anon/, 'anybody at all can ask')

    for (const file of ['mobile/src/lib/relay.js', 'src/lib/remote.js']) {
      const src = read(file)
      assert.match(src, /rpc\('computer_elsewhere'\)/, `${file} never asks`)
      assert.match(src, /return !error && data === true/, `${file} reads a failure as a yes`)
    }

    const phone = read('mobile/App.js').replace(/\s+/g, ' ')
    const waking = phone.slice(phone.indexOf('function Waking('))
    /* Not over Bluetooth (beta), where no computer is being looked for.
       Changed on purpose, 12 October 2026 (1.87.17): this pinned `long &&` in
       front, which asked only once the advice was up, so the advice opened on
       "make sure the computer is awake" and turned into the account warning
       a moment later, and again after every trip to Settings. It asks from
       the first second of looking now; the note still waits for `long`. */
    assert.match(waking, /useComputerElsewhere\(link\.link !== 'connected' && !bluetooth\)/, 'the phone never asks while it waits')
    /* "This iPad" on an iPad (device-word.mjs). */
    assert.match(waking, /This \$\{deviceNoun\(\)\} is signed in as \$\{email\}/, 'the phone does not say which account it is on')
    assert.match(waking, /Switch account on this \$\{deviceNoun\(\)\}/, 'the phone gives no way to change account')
    assert.match(read('mobile/src/screens/Settings.js'), /useComputerElsewhere\(link === 'no-answer'\)/, 'Setup never asks')

    /* "When the app is signed in on the wrong account it should say so on the
       main screen, not just in settings." */
    const wrong = read('mobile/src/components/WrongAccount.js').replace(/\s+/g, ' ')
    assert.match(wrong, /useComputerElsewhere\(active\)/, 'the stage never asks')
    assert.match(wrong, /This \$\{deviceNoun\(\)\} is signed in as \$\{email\}/, 'the stage does not say which account it is on')
    assert.match(wrong, /Switch account on this \$\{deviceNoun\(\)\}/, 'the stage gives no way to change account')
    assert.match(
      phone,
      /<WrongAccount active=\{auth === 'in' && !demo && !settling && screen === 'stage' && link\.link !== 'connected' && !bluetooth\}/,
      'the stage screen says nothing while the link is down on another account'
    )

    /* "Let's make sure that's added when there is no connection, and open the
       troubleshooting if it doesn't connect" — said of the browser's No unit
       found notice, and held at both ends. */
    const webApp = read('src/App.jsx').replace(/\s+/g, ' ')
    assert.match(webApp, /<AccountCheck link=\{link\} \/>/, 'the No unit found notice does not say which account')
    assert.match(webApp, /onClick=\{openConnectFix\}> Troubleshooting <\/button>/, 'the No unit found notice cannot open Troubleshooting')
    assert.match(webApp, /setFix\('connect'\) setSheet\('settings'\) setSetupPage\('help'\)/, 'the browser opens Troubleshooting somewhere other than the connect fix')
    const connectWeb = read('src/components/ConnectScreen.jsx')
    assert.match(connectWeb, /export function AccountCheck/, 'there is no account check for the notice to draw')
    assert.match(connectWeb, /computerElsewhere\(\)\.then/, 'the account check never asks about another account')
    assert.equal((connectWeb.match(/onClick=\{onTroubleshoot\}/g) || []).length, 2, 'Connecting and Not answering do not both offer Troubleshooting')
    assert.match(wrong, /label="Troubleshooting"/, 'the phone’s wrong-account note cannot open Troubleshooting')
    assert.match(phone, /setFixOpen\('connect'\) setFixFrom\('stage'\) setScreen\('fixes'\)/, 'the phone opens Troubleshooting somewhere other than the connect fix')
    assert.match(
      read('shared/troubleshooting.mjs'),
      /signed into the same account/,
      'the connect fix does not mention the account'
    )

    const web = read('src/components/ConnectScreen.jsx').replace(/\s+/g, ' ')
    assert.match(web, /computerElsewhere\(\)\.then/, 'the browser never asks')
    assert.match(web, /This browser is signed in as \$\{email\}/, 'the browser does not say which account it is on')
    assert.match(web, /\{mismatch \|\|/, 'the browser says the generic line over the real reason')
  })

  test('Give someone access is his alone, on both ends and on the server', async () => {
    /*
     * "Do I have an ability to manually activate an account for somebody?"
     * "Yes, build that in and only when logged into the [his iCloud address]
     * account."
     */
    const { ADMINS, isAdmin, accessAction } = await import('../shared/admin.mjs')
    const ME = '7dfe6912-e43b-49bf-84e4-b56afbd442b1'
    assert.deepEqual(ADMINS, [ME], 'the tools are for some other account')
    assert.ok(isAdmin(ME) && isAdmin(` ${ME.toUpperCase()} `), 'his own account does not get the tools')
    assert.ok(!isAdmin('00000000-0000-4000-8000-000000000000') && !isAdmin('') && !isAdmin(null), 'somebody else gets the tools')
    /*
     * BY THE ACCOUNT, NEVER BY THE ADDRESS. The lock was once an eight-character
     * djb2 hash of his email, and a made-up address with the same hash takes a
     * second to find: whoever signed up with one had every customer's details.
     * Nothing that looks like that may come back, here or on either server.
     */
    assert.ok(!isAdmin('someone@example.com'), 'an email address opens the tools')
    for (const file of ['shared/admin.mjs', 'supabase/functions/grant-access/index.ts', 'supabase/functions/owner-messages/index.ts']) {
      assert.ok(!/\bfold\(|5381|me\.email\)/.test(read(file).replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, '')), `${file} decides who is Justin from the email address again`)
    }

    /* The server holds the same list, and checks it before doing anything. */
    const server = read('supabase/functions/grant-access/index.ts')
    const copied = JSON.parse((server.match(/const ADMINS = (\[[^\]]*\])/) || [])[1]?.replace(/'/g, '"') || 'null')
    assert.deepEqual(copied, ADMINS, 'the server and the apps disagree about whose tools these are')
    /* Inside the handler, where the order is the order it runs in: the helpers
       above it (sales, usage) only run when the handler calls them. */
    const handler = server.slice(server.indexOf('Deno.serve('))
    const lock = handler.indexOf('ADMINS.includes(me.id)')
    /* And Paid but no computer yet's four (15 October 2026): the list, the switch, leaving somebody out, the sample. */
    /* And Sales at a glance's Handled (15 October 2026). */
    for (const step of ["rpc('account_details'", 'await sales()', 'await usage()', "rpc('owner_accounts'", 'confirmByHand(', 'await stuck()', 'reminderSwitch(', 'leaveOut(', 'reminderSample(', 'markHandled(']) {
      assert.ok(lock > 0 && handler.includes(step) && lock < handler.indexOf(step), `the server does ${step} before checking who is asking`)
    }
    /*
     * Help someone sign in: the one email they are missing, never both — and,
     * for an address that never confirmed, Confirm now beside the resend.
     * "He said he didn't get it. Can we set up a way for me to do that myself?"
     */
    const { signInHelp, signInHelpWords, messageSections } = await import('../shared/admin.mjs')
    assert.deepEqual(signInHelp({ found: true, email: 'a@b.c', details: { confirmed: null } }), { confirm: true, confirmNow: true, reset: false }, 'an unconfirmed address is offered a reset it cannot use, or no way past the email')
    assert.deepEqual(signInHelp({ found: true, email: 'a@b.c', details: { confirmed: '2026-10-01T09:00:00Z' } }), { confirm: false, confirmNow: false, reset: true }, 'a confirmed address is offered confirming again')
    assert.deepEqual(signInHelp({ found: false, email: 'a@b.c' }), { confirm: false, confirmNow: false, reset: false }, 'an address with no account is offered an email, or confirming')
    assert.deepEqual(signInHelp({ ok: false, message: 'Not allowed.' }), { confirm: false, confirmNow: false, reset: false })
    assert.match(signInHelpWords('reset', 'a@b.c').message, /a@b\.c/)
    assert.equal(signInHelpWords('confirm', 'a@b.c', 'nope').ok, false)
    assert.match(signInHelpWords('confirm', 'a@b.c').message, /^A new "confirm your email" link is on its way to a@b\.c\.$/)
    /* Confirmed by hand, in words he can pass on, and saying nobody told them: nothing is emailed. */
    assert.deepEqual(signInHelpWords('confirmNow', 'a@b.c'), {
      ok: true,
      message: 'a@b.c is confirmed. Nothing is emailed to them, so let them know they can sign in now with the password they chose. If they have forgotten it, send them a password reset.'
    })
    const notDone = signInHelpWords('confirmNow', 'a@b.c', 'The account service would not confirm it (500).')
    assert.equal(notDone.ok, false, 'a confirm that failed reads as done')
    assert.match(notDone.message, /^Their account was not confirmed: The account service would not confirm it \(500\)\.$/, 'a failed confirm says an email did not send')
    /*
     * The line under Confirm now: Resend first, that Confirm now sends no
     * email, and a check he can do on the address rather than "make sure".
     */
    const { CONFIRM_NOW_HINT, CONFIRM_NOW_WAITING, confirmNowHint } = await import('../shared/admin.mjs')
    assert.match(CONFIRM_NOW_HINT, /^Try Resend first\. If it still isn’t reaching them, Confirm their account now/, 'the line under Confirm now does not say to try Resend first')
    assert.match(CONFIRM_NOW_HINT, /with no email at all/, 'the line under Confirm now does not say it sends no email')
    assert.match(CONFIRM_NOW_HINT, /Only use it if they emailed you from this same address, so you know it’s spelled right and really theirs/, 'the line under Confirm now gives no check he can do on the address')
    assert.match(CONFIRM_NOW_HINT, /it lets whoever made the account sign in\.$/)
    /* And an address on the waiting list says so, before he taps: whoever made the account gets the unlock. */
    assert.equal(CONFIRM_NOW_WAITING, 'This address is on the waiting list for the full version you gave it, so whoever made the account gets that too, the first time they sign in.')
    const lookedUp = (waiting) => ({ ok: true, found: true, email: 'a@b.c', details: { confirmed: null, waiting } })
    assert.equal(confirmNowHint(lookedUp(true)), `${CONFIRM_NOW_HINT} ${CONFIRM_NOW_WAITING}`, 'a waiting address is not said to be one')
    for (const waiting of [false, null, undefined, 'yes']) {
      assert.equal(confirmNowHint(lookedUp(waiting)), CONFIRM_NOW_HINT, `waiting ${waiting} reads as waiting`)
    }
    assert.equal(confirmNowHint(null), CONFIRM_NOW_HINT)
    const listed = messageSections({ ok: true, messages: [{ id: 'x', kind: 'bug', message: 'It broke', contact: 'a@b.c', has_log: true, created_at: Date.now() }] })
    assert.match(listed[0].rows[0].value, /Something broken · today · log attached\nIt broke\nReply to a@b\.c/)
    assert.equal(listed[0].rows[0].id, 'x', 'a message cannot be opened from the list')

    /* What's live: the ledger read as it is written, and a phone behind the website said so. */
    const live = await import('../shared/whats-live.mjs')
    const ledger = live.readLedger(read('docs/expo-builds.md'))
    assert.ok(ledger.ios?.version && ledger.android?.version, 'What\u2019s live cannot read the build ledger')
    assert.match(ledger.left || '', /\d+ iOS, \d+ Android/, 'What\u2019s live lost the builds-left line')
    const sample = { site: { value: { version: '1.86.60', commit: 'abc1234', built: '2026-10-04 03:00' } }, release: { value: { tag_name: 'v1.86.59' } }, ledger: { value: read('docs/expo-builds.md') } }
    const behind = live.liveRows(sample, { kind: 'phone', version: '1.86.58' })
    assert.match(behind[0].value, /^v1\.86\.58, behind v1\.86\.60/, 'a phone behind the newest update is not told')
    assert.match(live.liveRows(sample, { kind: 'phone', version: '1.86.60' })[0].value, /up to date/)
    assert.match(live.liveRows({ site: { failed: 'offline' } }, {})[0].value, /Couldn't read it \(offline\)/, 'a source that failed reads as a version')
    /*
     * The oldest computer app the phones need, beside the newest there is —
     * and said loudly when the newest is older than that, because then every
     * computer is told to update to a version that does not exist.
     */
    const neededRow = (rows) => rows.find((r) => r.label === 'Computer app needed')?.value
    const { COMPUTER_NEEDED } = await import('../shared/versions.mjs')
    assert.equal(neededRow(live.liveRows({ ...sample, release: { value: { tag_name: `v${COMPUTER_NEEDED}` } } }, {})), `v${COMPUTER_NEEDED} or newer`, 'What\u2019s live does not say which computer app the phones need')
    assert.equal(neededRow(live.liveRows(sample, {}, '1.86.59')), 'v1.86.59 or newer', 'a newest release that is new enough is called too old')
    assert.match(neededRow(live.liveRows(sample, {}, '1.86.60')), /^v1\.86\.60 or newer, and the newest release is older than that/, 'a newest release older than the phones need is not said')
    assert.match(read('mobile/src/lib/whats-live.js'), /import \{ COMPUTER_NEEDED \} from '\.\/versions\.js'/, 'the phone\u2019s What\u2019s live imports a name Metro cannot find')
    assert.match(read('vite.config.js'), /fileName: 'version\.json'/, 'the website stopped saying which version it is')

    /* Messages from users: the same lock, checked before a single report is read. */
    const inbox = read('supabase/functions/owner-messages/index.ts')
    assert.deepEqual(JSON.parse((inbox.match(/const ADMINS = (\[[^\]]*\])/) || [])[1]?.replace(/'/g, '"') || 'null'), ADMINS, 'the messages server and the apps disagree about whose tools these are')
    assert.ok(inbox.indexOf('ADMINS.includes(me.id)') > 0 && inbox.indexOf('ADMINS.includes(me.id)') < inbox.indexOf('await rows('), 'the messages server reads reports before checking who is asking')
    assert.ok(!/method: 'DELETE'|method: 'PATCH'/.test(inbox), 'the messages page can change or delete a report')
    assert.match(read('mobile/src/screens/Settings.js'), /\{page === 'messages' && isAdmin\(account\?\.id\) \?/)
    assert.match(read('src/App.jsx'), /\{setupPage === 'messages' && isAdmin\(link\.account\?\.id\) \?/)
    assert.match(server, /actions\/grant_entitlement/, 'the server does not grant through RevenueCat')
    assert.match(server, /actions\/revoke_granted_entitlement/, 'the server cannot take a grant back')
    const sql = read('supabase/migrations/20260923_account_for_email.sql')
    assert.match(sql, /revoke all on function public\.account_for_email\(text\) from public, anon, authenticated/, 'a client can look up whether an email has an account')

    /* Both ends draw the page only for him. */
    assert.match(read('mobile/src/screens/Settings.js'), /\{page === 'access' && isAdmin\(account\?\.id\) \?/)
    assert.match(read('src/App.jsx'), /\{setupPage === 'access' && isAdmin\(link\.account\?\.id\) \?/)

    /* And the call never throws, whatever the line does. */
    const down = await accessAction({ url: 'x', anonKey: 'k', token: 't', action: 'check', email: 'a@b.c', fetchImpl: () => Promise.reject(new Error('offline')) })
    assert.equal(down.ok, false)
    const signedOut = await accessAction({ url: 'x', anonKey: 'k', token: null, action: 'check', email: 'a@b.c' })
    assert.equal(signedOut.message, 'Sign in first.')
  })

  test('Which unit names the unit on each computer, and switching reads the new one', async () => {
    const { unitFrom, unitChoices } = await import('../shared/relay-rules.mjs')
    const raw = async (a) => a
    /* One answer to an addressed /healthz is that computer's unit. */
    assert.deepEqual(await unitFrom([JSON.stringify({ ok: true, api: { version: 2 }, device: 'FM3' })], raw), { model: 'FM3', plugged: true })
    assert.deepEqual(await unitFrom([JSON.stringify({ ok: false, device: 'AM4' })], raw), { model: 'AM4', plugged: false })
    /* Two answers mean a computer too old to be addressed: whose is whose cannot be said. */
    assert.equal(await unitFrom([JSON.stringify({ ok: true, device: 'FM3' }), JSON.stringify({ ok: true, device: 'AM4' })], raw), null)
    assert.equal(await unitFrom([], raw), null)
    /* "It's just showing both listed as FM3": an AM4's computer says FM3 on /healthz
       (the profile it started with) and AM4 on /device (the unit it detected). */
    assert.deepEqual(
      await unitFrom([JSON.stringify({ ok: true, device: 'FM3' })], raw, [JSON.stringify({ model: 'AM4', modelId: 21 })]),
      { model: 'AM4', plugged: true }
    )
    /* A computer too old to answer /device still has its /healthz word. */
    assert.deepEqual(await unitFrom([JSON.stringify({ ok: true, device: 'FM3' })], raw, []), { model: 'FM3', plugged: true })
    for (const file of ['mobile/src/lib/relay.js', 'src/lib/remote.js']) {
      assert.match(read(file), /collectAnswers\(\{ path: '\/device', host: name, windowMs, sleep \}\)/, `${file} names the unit from /healthz, which says FM3 for an AM4`)
    }
    assert.equal(await unitFrom(['not json'], raw), null)

    const rows = unitChoices(['Studio iMac', 'MacBook Pro', 'Old Mac'], {
      'Studio iMac': { model: 'AM4', plugged: true },
      'MacBook Pro': { model: 'FM3', plugged: true }
    }, 'MacBook Pro')
    assert.deepEqual(rows.map((r) => [r.label, r.detail, r.on]), [
      ['AM4', 'on Studio iMac', false],
      ['FM3', 'on MacBook Pro', true],
      ['Old Mac', 'It didn’t say which unit in time.', false]
    ])
    /* While it is asked again (link.js askUnknownUnits), said so; and never sent off to update a computer app that may be fine. */
    assert.equal(unitChoices(['Old Mac', 'MacBook Pro'], { 'MacBook Pro': { model: 'FM3', plugged: true } }, null, true).find((r) => r.name === 'Old Mac').detail, 'Asking it which unit…')
    const { unitNotSaid } = await import('../shared/relay-rules.mjs')
    assert.ok(![unitNotSaid(false), unitNotSaid(true)].some((words) => /update/i.test(words)), 'Which unit still tells a slow computer to update')
    /* Nothing plugged in still answers, and goes last. */
    const empty = unitChoices(['A', 'B'], { A: { model: 'FM3', plugged: false }, B: { model: 'AM4', plugged: true } })
    assert.deepEqual(empty.map((r) => r.label), ['AM4', 'No unit plugged in'])

    for (const file of ['mobile/src/lib/relay.js', 'src/lib/remote.js']) {
      const src = read(file)
      assert.match(src, /units = hosts\.length > 1 \? await readUnits\(\{ windowMs, sleep \}\) : \{\}/, `${file} does not ask which unit each computer has`)
      assert.match(src, /collectAnswers\(\{ path: '\/healthz', host: name, windowMs, sleep \}\)/, `${file} asks which unit without addressing the computer`)
    }
    /* Picking a unit on the phone reads it again, start to finish. */
    const link = read('mobile/src/lib/link.js')
    assert.match(link, /export async function chooseHost\(name\) \{\s*const ok = await pickHost\(name\)[\s\S]{0,900}await refreshAll\(\)/, 'the phone switches unit but keeps the old one on screen')
    const settings = read('mobile/src/screens/Settings.js')
    assert.match(settings, /<Section>Which unit<\/Section>[\s\S]{0,300}unitChoices\(hosts, units, chosen, unitsAsking\)/)
    assert.ok(!settings.includes('<Section>Which computer</Section>'), 'the phone still says Which computer')
    const app = read('src/App.jsx')
    assert.match(app, /title="Which unit"[\s\S]{0,400}unitChoices\(link\.hosts, link\.units, link\.chosenHost, link\.unitsAsking\)[\s\S]{0,500}await chooseHost\(row\.name\)/, 'the website switches unit but does not read the new one')
  })

  test('a live unit name opens Which unit when two units are on, like the demo', () => {
    const app = read('mobile/App.js')
    assert.match(app, /<LiveUnit\s+open=\{pickLive && !demo\}[\s\S]{0,200}hosts=\{link\.hosts\}\s+units=\{link\.units\}\s+chosen=\{link\.chosenHost\}/)
    const sheet = read('mobile/src/components/LiveUnit.js')
    assert.match(sheet, /unitChoices\(hosts, units, chosen, asking\)/)
    assert.match(sheet, /await chooseHost\(row\.name\)[\s\S]{0,160}onClose\(\)/, 'the sheet closes before the new unit is read')
    const web = read('src/App.jsx')
    assert.match(web, /if \(!isDemo\(\) && link\.role === 'remote' && link\.hosts\.length > 1\) \{\s*setSheet\('units'\)/)
    assert.match(web, /open=\{sheet === 'units'\}[\s\S]{0,400}unitChoices\(link\.hosts, link\.units, link\.chosenHost, link\.unitsAsking\)[\s\S]{0,600}await chooseHost\(row\.name\)/)
  })

  /*
   * "The unit metronome click is not working. It doesn't turn it on the unit
   * on the FM3 or the AM4. It only works on the phone." On an AM4, and over
   * Bluetooth, the app cannot switch the unit's click — and Unit picked there
   * meant nothing clicked anywhere.
   */
  test('where the unit’s click cannot be switched, Unit is not offered and the phone keeps time', async () => {
    const m = await import('../shared/metronome.mjs')
    assert.deepEqual(m.unitClick('fm3'), { can: true })
    assert.equal(m.unitClick('fm3', { bluetooth: true }).can, false)
    assert.match(m.unitClick('fm3', { bluetooth: true }).why, /Over Bluetooth/)
    assert.equal(m.unitClick('am4').can, false, 'the AM4’s click is written again, the write that froze it')
    assert.match(m.unitClick('am4').why, /AM4/)
    assert.equal(m.unitClick('vp4').can, false)
    /* Unit picked, the unit unable: the phone clicks, the unit is never told. */
    const unit = { on: true, where: 'unit' }
    assert.deepEqual(m.clicks(unit, false), { unit: false, phone: true, watch: false }, 'nothing clicks anywhere when the unit cannot')
    assert.deepEqual(m.clicks(unit, true), { unit: true, phone: false, watch: false })
    assert.deepEqual(m.clicks({ on: true, where: 'both' }, false), { unit: false, phone: true, watch: false })
    assert.deepEqual(m.clicks({ on: false, where: 'unit' }, false), { unit: false, phone: false, watch: false })
    assert.deepEqual(m.clicks(unit), m.clicks(unit, true), 'the old one-argument call changed meaning')
    /* Only Phone offered where the unit cannot click. */
    assert.deepEqual(m.placesFor(false).map((p) => p.key), ['phone'])
    assert.deepEqual(m.placesFor(true).map((p) => p.key), ['unit', 'phone', 'both'])
    /* And the Settings row says where it really clicks. */
    assert.match(m.metronomeNote(unit, 'fm3', 120, { bluetooth: true }), /on the phone$/)
    assert.match(m.metronomeNote(unit, 'fm3', 120), /on the unit$/)
    assert.match(m.metronomeNote(unit, 'am4', 120), /only the phone keeps time/)
    /* The phone's own click hears the same rule, from the unit and the link it is on. */
    const metronome = read('mobile/src/lib/metronome.js').replace(/\s+/g, ' ')
    assert.match(metronome, /const \{ can, heard: heardOn \} = useUnitCan\(\) const on = clicks\(s, can, heardOn\)\.phone/, 'the phone stays silent where the unit cannot click')
    assert.match(metronome, /const can = unitClick\(slug, here\)\.can const before = clicks\(setting, can\)\.unit/)
    assert.match(metronome, /if \(!clicks\(setting, unitClick\(slug, \{ bluetooth \}\)\.can\)\.unit\) \{ stopFollowing\(\) return \} switchUnit\(slug, true\)/)
    /* "ok" only means the unit did not object: what it then says it is at goes into the log. */
    assert.match(metronome, /read: \(\) => readUnitMetronome\(slug\)/)
    /* And the demo's unit makes no sound, so Unit there is the phone. */
    assert.equal(m.unitClick('fm3', { demo: true }).can, false, 'the demo says the unit clicks, and nothing does')
    assert.match(m.unitClick('fm3', { demo: true }).why, /demo/)
    assert.match(metronome, /const demo = isDemo\(\) const bluetooth = useBluetoothOn\(\) && !demo return \{ can: unitClick\(slug, \{ bluetooth, demo \}\)\.can/)
    /* Only Phone offered, so Phone is lit, and tapping it keeps a saved Unit. */
    assert.equal(m.placeLit(unit, 'phone', false), true, 'the one row offered is not lit, though it is what clicks')
    assert.equal(m.placeLit(unit, 'unit', true), true)
    assert.equal(m.placeLit(unit, 'phone', true), false)
    const settings = read('mobile/src/screens/Settings.js').replace(/\s+/g, ' ')
    assert.match(settings, /on=\{placeLit\(clickSetting, p\.key, unitCan\.can\)\} onPress=\{\(\) => \(unitCan\.can \? changeClick\(\{ where: p\.key \}\) : null\)\}/, 'tapping the only row wipes a saved Unit')
    const web = read('src/App.jsx').replace(/\s+/g, ' ')
    assert.match(web, /placeLit\(clickSetting, p\.key, unitCan\.can\) \? ' ✓' : ''/)
    assert.match(web, /if \(!unitCan\.can\) return wakeScreenClick\(\) setClickSaid\(null\)/, 'the lit row’s press no longer lets the beep start')
    const device = read('mobile/src/lib/device.js').replace(/\s+/g, ' ')
    assert.match(device, /export async function readUnitMetronome\(slug\) \{ const how = unitMetronome\(slug\) if \(!how \|\| how\.kind !== 'block' \|\| demoDevice\(\)\) return null/)
    assert.match(device, /const eid = how\.eid try \{ const res = await post\(`\/preset\/blocks\/\$\{eid\}\/readrange`, \{ pids: \[how\.paramId\] \}\)/)
    /* The read-back route is one a phone may use through the relay. */
    const { hostAllows } = await import('../shared/relay-rules.mjs')
    assert.equal(hostAllows('POST', '/preset/blocks/1/readrange'), true)
    /* And the demo's units click without "the unit didn't take it". */
    assert.match(device, /if \(!ask \|\| demoDevice\(\)\) return Promise\.resolve\(ask \? \{ ok: true, simulated: true \} : \{ ok: false, unsupported: true \}\)/)
  })

  test('under Unit the phone keeps time until the unit says its own click is on', async () => {
    /*
     * "It doesn't turn it on the unit on the FM3 or the AM4. It only works on
     * the phone." The FM3 answers the write "ok" whenever it does not object,
     * and nobody has seen one act on its switch — so Unit on his FM3 clicked
     * nowhere. Now the phone keeps time under Unit until the unit's switch
     * reads back as on, and stops the moment it does.
     */
    const m = await import('../shared/metronome.mjs')
    const unit = { on: true, where: 'unit' }
    assert.deepEqual(m.clicks(unit, true, false), { unit: true, phone: true, watch: false }, 'Unit with nothing heard clicks nowhere')
    assert.deepEqual(m.clicks(unit, true, true), { unit: true, phone: false, watch: false })
    assert.deepEqual(m.clicks({ on: true, where: 'phone' }, true, false), { unit: false, phone: true, watch: false })
    assert.deepEqual(m.clicks({ on: true, where: 'both' }, true, false), { unit: true, phone: true, watch: false })
    assert.equal(m.switchHeardOn(1), true)
    assert.equal(m.switchHeardOn(0), false)
    assert.equal(m.switchHeardOn(null), false, 'no answer is taken for a click')
    assert.match(m.metronomeNote(unit, 'fm3', 120, { heard: false }), /on the phone until the unit says its click is on$/)
    assert.match(m.metronomeNote(unit, 'fm3', 120, { heard: true }), /on the unit$/)

    /* followSwitch: soon while not heard, then every half minute; never once it is not wanted. */
    {
      /* Run on a list of due timers, so each wait can be fired by hand. */
      const due = []
      const answers = []
      let value = 0
      let wanted = true
      const flush = async () => {
        for (let i = 0; i < 4; i++) await null
      }
      const stopIt = m.followSwitch({
        read: async () => {
          if (value === 'throw') throw new Error('no answer')
          return value
        },
        wanted: () => wanted,
        answer: (on) => answers.push(on),
        wait: (fn, ms) => (due.push({ fn, ms }), due.length),
        stop: (id) => {
          due[id - 1].stopped = true
        }
      })
      const fire = async () => {
        const next = due.find((d) => !d.fired && !d.stopped)
        next.fired = true
        next.fn()
        await flush()
        return next.ms
      }
      await flush()
      assert.deepEqual(due.map((d) => d.ms), [1000])
      assert.equal(await fire(), 1000)
      assert.equal(await fire(), 3000)
      value = 'throw'
      assert.equal(await fire(), 10000)
      assert.deepEqual(answers, [false, false, false, false], 'a read that threw is taken for a click')
      value = 1
      assert.equal(await fire(), 30000)
      assert.deepEqual(answers.slice(-1), [true])
      assert.equal(due.at(-1).ms, 30000, 'a switch heard on is not checked every half minute')
      wanted = false
      await fire()
      assert.equal(due.filter((d) => !d.fired && !d.stopped).length, 0, 'a click nobody wants is still asked about')
      assert.equal(answers.length, 5)
      stopIt()
    }

    /* Run, not read: the phone's metronome.js beside stand-ins for the phone and a unit that answers. */
    const { dir, click, unitEnd, log, clock, settle } = await clickOnTheBench()
    try {

      /* Unit picked on an FM3 that says nothing back: written on, and the phone keeps time. */
      await click.setMetronome({ on: true, where: 'unit' }, 'fm3')
      await settle()
      assert.deepEqual(unitEnd.writes, ['fm3 on'])
      assert.equal(click.unitHeardOn('fm3'), false, 'a unit that said nothing is taken to be clicking')
      assert.ok(log.said.some((l) => /did not say where its metronome switch is/.test(l)), 'the log does not say the unit was silent')
      assert.equal(click.usePhoneClick(120), true, 'Unit with nothing heard leaves the phone silent')

      /*
       * And asked again. The switch turned on at the FM3 by hand, with no
       * setting changed here: a second later the phone hears it and stops.
       */
      unitEnd.__answer(1)
      await clock.advance(1000)
      assert.equal(click.unitHeardOn('fm3'), true, 'a switch turned on at the unit is never noticed')
      assert.equal(click.usePhoneClick(120), false, 'the phone clicks over a unit that says it is clicking')
      /* Turned off at the unit: within half a minute the phone takes over again. */
      unitEnd.__answer(0)
      await clock.advance(30000)
      assert.equal(click.unitHeardOn('fm3'), false, 'a switch turned off at the unit leaves nothing clicking')
      assert.equal(click.usePhoneClick(120), true)
      /* The log hears each change once, not every half minute. */
      unitEnd.__answer(1)
      await clock.advance(10000)
      assert.equal(click.unitHeardOn('fm3'), true)
      const before = log.said.length
      await clock.advance(90000)
      assert.equal(log.said.length, before, 'the same answer is logged on every read')
      unitEnd.__answer(null)

      /* Picked again once the FM3 does answer: heard on, and only for that unit. */
      unitEnd.__answer(1)
      await click.setMetronome({ where: 'phone' }, 'fm3')
      await click.setMetronome({ where: 'unit' }, 'fm3')
      await settle()
      assert.deepEqual(unitEnd.writes, ['fm3 on', 'fm3 off', 'fm3 on'])
      assert.equal(click.unitHeardOn('fm3'), true, 'the unit said its click is on, and the phone keeps clicking over it')
      assert.equal(click.unitHeardOn('fm9'), false, 'one unit heard is every unit heard')
      assert.ok(log.said.some((l) => /the unit says its metronome switch is at 1/.test(l)))

      /* Off is believed at once: the phone never goes quiet waiting on an answer. */
      await click.setMetronome({ on: false }, 'fm3')
      assert.equal(click.unitHeardOn('fm3'), false)
      /* And nothing is asked again once the setting no longer asks for the unit. */
      await settle()
      const asked = unitEnd.reads
      await clock.advance(120000)
      assert.equal(unitEnd.reads, asked, 'the unit is still asked about a click nobody wants')
      assert.equal(clock.pending(), 0)

      /* An answer of "off" after an "on" is not a click either. */
      unitEnd.__answer(0)
      await click.setMetronome({ on: true }, 'fm3')
      await settle()
      assert.equal(click.unitHeardOn('fm3'), false, 'a switch read back as off is heard as on')

      /* And a unit that goes is no longer heard: the next one has to say so again. */
      unitEnd.__answer(1)
      click.useUnitMetronome('fm3', true)
      globalThis.__clickEffect()
      await settle()
      assert.equal(click.unitHeardOn('fm3'), true, 'a unit arriving with Unit on is not asked where its switch is')
      click.useUnitMetronome('fm3', false)
      globalThis.__clickEffect()
      assert.equal(click.unitHeardOn('fm3'), false, 'a unit that went is still heard clicking')
      const gone = unitEnd.reads
      await clock.advance(120000)
      assert.equal(unitEnd.reads, gone, 'a unit that went is still asked where its switch is')
      /* Bluetooth turned on with Unit picked: the unit is not asked again either. */
      click.useUnitMetronome('fm3', true)
      globalThis.__clickEffect()
      await settle()
      click.useUnitMetronome('fm3', true, { bluetooth: true })
      globalThis.__clickEffect()
      const blue = unitEnd.reads
      await clock.advance(120000)
      assert.equal(unitEnd.reads, blue, 'the unit is still asked over Bluetooth, where it cannot be switched')
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })

  test('the phone’s click, flash and tap land together on an iPhone: rewound a beat ahead, the audio kept awake, the flash after the sound', async () => {
    /*
     * "The visual edge screen flash is not actually matching up with the sound
     * that the phone makes." The flash was asked for on the beat; the click,
     * on an iPhone, waited on a rewind that only runs after the beat's own
     * code, from an audio session that had been let go after the last click.
     */
    const { dir, click, clock, audio, feedback } = await clickOnTheBench('ios')
    try {
      await click.setMetronome({ on: true, where: 'phone' }, 'fm3')
      const flashes = []
      assert.equal(click.usePhoneClick(120, () => flashes.push(clock.now())), true)
      const stop = globalThis.__clickEffect()
      await clock.advance(0)
      const t0 = Number(audio.calls.find((c) => c.startsWith('play')).split('@')[1])

      /* Two players, both keeping the audio awake, both made before the first beat. */
      assert.equal(audio.made.length, 2, 'one player rewound on the beat it plays')
      assert.ok(audio.made.every((p) => p.opts.keepAudioSessionActive === true && p.src === 'click'), 'the audio is let go after every click')
      assert.ok(audio.calls.indexOf('mode @0') !== -1 && audio.calls.indexOf('mode @0') < audio.calls.findIndex((c) => c.startsWith('play')), 'the first click plays before the audio is set up')

      await clock.advance(1600)
      /* From the first beat: the rewinds before it are the run's own, every player back at the top. */
      const first = audio.calls.findIndex((c) => c.startsWith('play'))
      assert.deepEqual(audio.calls.slice(first - 4, first).map((c) => c.split(' @')[0]), ['pause 0', 'seek 0', 'pause 1', 'seek 1'])
      const beats = audio.calls.slice(first).filter((c) => /^(play|seek)/.test(c))
      assert.deepEqual(
        beats,
        [`play 0 @${t0}`, `seek 1 @${t0}`, `play 1 @${t0 + 500}`, `seek 0 @${t0 + 500}`, `play 0 @${t0 + 1000}`, `seek 1 @${t0 + 1000}`, `play 1 @${t0 + 1500}`, `seek 0 @${t0 + 1500}`],
        'the player that sounds is not the one rewound a beat ago'
      )
      /* The flash and the tap wait for the sound: FLASH_LEAD, 40 ms on an iPhone. */
      assert.deepEqual(flashes, [t0 + 40, t0 + 540, t0 + 1040, t0 + 1540], 'the flash does not wait for the click')
      assert.equal(feedback.ticks, flashes.length, 'the tap is not with the flash')

      /* Flash timing moves it at once, by ear. */
      click.setFlashTiming(60)
      assert.equal(click.flashTiming(), 60)
      await clock.advance(500)
      assert.equal(flashes.at(-1), t0 + 2100, 'Flash timing does not move the flash')
      click.setFlashTiming(0)

      /* Stopped between a click and its flash: the flash never comes, nor the tap. */
      await clock.advance(410)
      assert.ok(audio.calls.includes(`play 1 @${t0 + 2500}`) && flashes.at(-1) === t0 + 2100, 'the test did not stop between a click and its flash')
      const seen = flashes.length
      const tapped = feedback.ticks
      stop()
      await clock.advance(1000)
      assert.equal(flashes.length, seen, 'a flash lands after the click stopped')
      assert.equal(feedback.ticks, tapped, 'a tap lands after the click stopped')

      /* Started again within two seconds (a tap-tempo press): the audio is not let go under it. */
      click.usePhoneClick(120, () => flashes.push(clock.now()))
      const stopAgain = globalThis.__clickEffect()
      await clock.advance(4000)
      assert.ok(!audio.calls.some((c) => c.startsWith('session false')), 'a restart lets go of the audio under the new click')
      /* And every player is back at the top before a new run, whatever turn the last one stopped on. */
      stopAgain()
      await clock.advance(1999)
      assert.ok(!audio.calls.some((c) => c.startsWith('session false')))
      await clock.advance(1)
      assert.equal(audio.calls.filter((c) => c.startsWith('session false')).length, 1, 'the audio is held after the click stopped')

      /* How late the click starts, into the log once a run: here it never starts, so the last probe. */
      const log = await import(pathToFileURL(join(dir, 'debugLog.js')).href)
      assert.ok(log.said.some((l) => /the click starts about 100 ms after the beat; the flash comes 40 ms after it/.test(l)), 'the click’s real delay never reaches the log')
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })

  test('on Android the click has silence in front for the fade-in, one player, and the flash waits for it', async () => {
    const { dir, click, clock, audio, feedback } = await clickOnTheBench('android')
    try {
      await click.setMetronome({ on: true, where: 'phone' }, 'fm3')
      const flashes = []
      click.usePhoneClick(120, () => flashes.push(clock.now()))
      const stop = globalThis.__clickEffect()
      await clock.advance(0)
      const t0 = Number(audio.calls.find((c) => c.startsWith('play')).split('@')[1])
      assert.equal(audio.made.length, 1)
      assert.equal(audio.made[0].src, 'click-pad', 'Android’s fade-in takes the click with it')
      assert.notEqual(audio.made[0].opts.keepAudioSessionActive, true)
      await clock.advance(1000)
      /* Its seek and its play go in order, so the rewind comes first on the beat itself. */
      const first = audio.calls.findIndex((c) => c.startsWith('play'))
      const beats = audio.calls.slice(first - 1).filter((c) => /^(play|seek)/.test(c))
      assert.deepEqual(beats, [`seek 0 @${t0}`, `play 0 @${t0}`, `seek 0 @${t0 + 500}`, `play 0 @${t0 + 500}`, `seek 0 @${t0 + 1000}`, `play 0 @${t0 + 1000}`])
      assert.deepEqual(flashes, [t0 + 100, t0 + 600], 'the flash does not wait for Android’s click')
      assert.equal(feedback.ticks, 2)
      stop()
      await clock.advance(3000)
      assert.ok(!audio.calls.some((c) => c.startsWith('session')), 'Android is told to let go of an iPhone’s audio session')
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })

  test('the padded click is the click with 25 ms of silence in front, and nothing else', () => {
    const wav = (f) => {
      const b = readFileSync(new URL(`../mobile/assets/${f}`, import.meta.url))
      let o = 12
      const chunks = {}
      while (o < b.length) {
        const id = b.toString('ascii', o, o + 4)
        const n = b.readUInt32LE(o + 4)
        chunks[id] = b.subarray(o + 8, o + 8 + n)
        o += 8 + n + (n & 1)
      }
      return chunks
    }
    const plain = wav('click.wav')
    const pad = wav('click-pad.wav')
    assert.deepEqual(pad['fmt '], plain['fmt '], 'the padded click is another format')
    const rate = plain['fmt '].readUInt32LE(4)
    const frame = (plain['fmt '].readUInt16LE(2) * plain['fmt '].readUInt16LE(14)) / 8
    const lead = pad.data.length - plain.data.length
    assert.ok(Math.abs((lead / frame / rate) * 1000 - 25) < 0.1, `the silence in front is not 25 ms: ${(lead / frame / rate) * 1000}`)
    assert.ok(pad.data.subarray(0, lead).every((x) => x === 0), 'what is in front of the click is not silence')
    assert.ok(pad.data.subarray(lead).equals(plain.data), 'the padded click is not the same click')
    /* And FLASH_LEAD counts it. */
    const metronome = read('mobile/src/lib/metronome.js')
    assert.match(metronome, /: \[createAudioPlayer\(clickPadded\)\]/, 'Android plays the click its fade-in swallows')
  })

  test('the metronome turns on and off in the volume pop-up, the way Settings turns it, at both ends', () => {
    /* "Make it so the metronome can be turned on and off in the volume section of the app." */
    const flat = (f) => read(f).replace(/\s+/g, ' ')
    const volume = flat('mobile/src/components/Volume.js')
    const sw = volume.indexOf('<MetronomeSwitch />')
    assert.ok(sw > 0, 'the volume pop-up has no metronome switch')
    assert.ok(sw > volume.indexOf('Use the knob on the unit.'), 'the switch is inside the level’s own notes, and goes with them')
    assert.ok(sw < volume.indexOf('<Press label="Done"'), 'the switch is under Done')
    const phone = flat('mobile/src/components/MetronomeSwitch.js')
    /* The same "here" as Settings → Metronome, so the unit is written exactly as Settings writes it. */
    assert.match(phone, /const clickHere = \{ bluetooth: bluetooth && !demo, demo \} const unitCan = unitClick\(slug, clickHere\)/)
    assert.match(phone, /await setMetronome\(\{ on: !setting\.on \}, slug, clickHere\)/, 'the pop-up writes the unit another way')
    assert.match(phone, /label=\{setting\.on \? 'Metronome on' : 'Metronome off'\}/)
    assert.match(phone, /The unit didn’t take it\. Check it’s connected, then try again\./)
    /* Never a second click: the pop-up only switches it, MetronomeBeat over the app does the clicking. */
    assert.doesNotMatch(phone, /usePhoneClick|MetronomeBeat/, 'the pop-up starts a second click')
    const web = flat('src/App.jsx')
    assert.match(web, /<Volume eid=\{outputEid\} preset=\{preset\} onError=\{setError\} \/> \) : null\} \{\/\*[^*]*\*\/\} \{sheet === 'volume' \? <MetronomeSwitch slug=\{slugOfUnit\(device\)\} \/> : null\} <\/Sheet>/, 'the browser’s Volume sheet has no metronome switch')
    const browser = flat('src/components/MetronomeSwitch.jsx')
    assert.match(browser, /const unitCan = unitClick\(slug, \{ demo: isDemo\(\), ours: 'this screen' \}\)/)
    assert.match(browser, /await setMetronome\(\{ on: !setting\.on \}, slug\)/)
  })

  /*
   * "On the tap tempo button where you hold it down and it pops up to enter
   * the tempo, make it so it highlights it so that they can just start
   * typing. Right now they have to hit the back button to delete the tempo
   * to reenter it."
   */
  test('the phone’s tempo box opens on the tempo, all of it selected, so a digit replaces it and Backspace clears it', async () => {
    const f = await import('../mobile/src/lib/tempo-field.js')
    const { checkBpm } = await import('../shared/tempo.mjs')
    /* What the phone does with a key over a selection: replaces it, or for Backspace deletes it. */
    const key = (text, sel, k) => {
      const s = sel || { start: text.length, end: text.length }
      if (k === 'Backspace') return s.start !== s.end ? text.slice(0, s.start) + text.slice(s.end) : text.slice(0, Math.max(0, s.start - 1)) + text.slice(s.end)
      return text.slice(0, s.start) + k + text.slice(s.end)
    }
    let field = f.freshField()
    /* The first frame: the number is in, and the whole of it is asked for. */
    assert.equal(f.shownText(field, 120), '120', 'the box opens empty, and the tempo arrives after the cursor')
    assert.deepEqual(f.heldSelection(field, '120'), { start: 0, end: 3 }, 'the box opens with the tempo not selected')
    assert.equal(f.shownText(field, 99.6), '100')
    assert.deepEqual(f.heldSelection(field, '100'), { start: 0, end: 3 })
    /* The phone parking its caret at the end as the field takes focus: the selection is put back, not given up. */
    field = f.selectionMoved(field, { start: 3, end: 3 }, '120')
    assert.equal(field.held, true, 'the phone’s own caret, as the keyboard came up, took the selection away')
    assert.deepEqual(f.heldSelection(field, '120'), { start: 0, end: 3 })
    field = f.selectionMoved(field, { start: 0, end: 3 }, '120')
    assert.equal(field.held, true)
    assert.equal(field.seen, '120')
    /* Typing a digit over it replaces the whole number. */
    const typed = f.typedInto(field, key('120', f.heldSelection(field, '120'), '1'))
    assert.equal(f.shownText(typed, 120), '1', 'a digit typed into the box was added to the tempo instead of replacing it')
    assert.equal(f.heldSelection(typed, '1'), undefined, 'the selection is still held after a keystroke, so the next digit replaces the first')
    const more = f.typedInto(typed, key('1', { start: 1, end: 1 }, '3'))
    assert.equal(f.typedInto(more, key('13', { start: 2, end: 2 }, '2')).typed, '132')
    /* Backspace empties it, and an empty box stays empty rather than springing back to the tempo. */
    const cleared = f.typedInto(field, key('120', f.heldSelection(field, '120'), 'Backspace'))
    assert.equal(f.shownText(cleared, 120), '', 'Backspace left part of the tempo in the box')
    assert.equal(checkBpm(f.shownText(cleared, 120)).empty, true, 'Set on an emptied box no longer closes without a write')
    /* Anything but digits never gets in. */
    assert.equal(f.typedInto(field, '1a2.5').typed, '125')
    /* A finger moving the cursor after the number was seen selected (Android reports it): the cursor is theirs. */
    assert.equal(f.selectionMoved(field, { start: 1, end: 1 }, '120').held, false, 'a thumb can never put the cursor anywhere')
    /*
     * An iPhone's own stream, which never reports a selection the code made:
     * at most the caret it parks at the end as the field takes focus, then
     * nothing while the box selects the number itself once it is up, then a
     * finger. Without the box noting what it did, that finger snapped back.
     */
    let ios = f.freshField()
    ios = f.selectionMoved(ios, { start: 3, end: 3 }, '120')
    assert.equal(ios.held, true, 'on an iPhone the caret parked as the field took focus gave up the selection')
    ios = f.selectedByHand(ios)
    assert.equal(ios.held, true)
    assert.deepEqual(f.heldSelection(ios, '120'), { start: 0, end: 3 }, 'selecting it by hand let go of the selection')
    assert.equal(f.selectionMoved(ios, { start: 1, end: 1 }, '120').held, false, 'on an iPhone a thumb in the number snaps back to the whole of it')
    /* The tempo moving under the open box: TextInput sends the selection down with the new number, so a finger after it is still a finger. */
    assert.equal(f.selectionMoved(ios, { start: 0, end: 3 }, '132').held, true)
    assert.equal(f.selectionMoved(ios, { start: 2, end: 2 }, '132').held, false, 'after the tempo moved, a thumb in the number snaps back on an iPhone')
    /* Before the box is up, nothing is known: a caret then is the phone's, and the hold puts it back. */
    assert.equal(f.selectionMoved(f.freshField(), { start: 1, end: 1 }, '120').held, true)
    /* After a keystroke there is nothing to note. */
    const after = f.typedInto(ios, '5')
    assert.equal(f.selectedByHand(after), after)
    /* A new number from the unit while nothing is typed: followed, and its own caret is not taken for a finger. */
    assert.equal(f.shownText(field, 132), '132', 'the box holds a stale tempo while the unit moves under it')
    assert.equal(f.selectionMoved(field, { start: 3, end: 3 }, '132').held, true, 'the caret a new number brought with it gave up the selection')
    /* No tempo yet: an empty box with nothing to select. */
    assert.equal(f.shownText(f.freshField(), undefined), '')
    assert.equal(f.heldSelection(f.freshField(), ''), undefined)
    /* Pure: nothing imported, so this is the rule the app runs. */
    assert.doesNotMatch(withoutComments(read('mobile/src/lib/tempo-field.js')), /^\s*import /m)
  })

  test('the phone’s tempo box draws the number from its first frame and hands TextInput the selection, on both phones', () => {
    const src = read('mobile/src/components/TempoBox.js')
    const code = withoutComments(src)
    const flat = code.replace(/\s+/g, ' ')
    /* An effect runs after the frame is on screen: that is how the field took focus empty. */
    assert.doesNotMatch(code, /useEffect/, 'the box fills itself in an effect again, after the field has taken focus empty')
    assert.match(flat, /if \(!!open !== wasOpen\) \{ setWasOpen\(!!open\) if \(open\) \{ setField\(freshField\(\)\)/, 'the box is not reset as it opens, on its first frame')
    assert.match(flat, /const typed = shownText\(field, bpm\)/)
    const input = flat.slice(flat.indexOf('<TextInput'), flat.indexOf('/>', flat.indexOf('<TextInput')))
    for (const prop of [
      /\bautoFocus\b/,
      /\bselectTextOnFocus\b/,
      /value=\{typed\}/,
      /selection=\{heldSelection\(field, typed\)\}/,
      /onSelectionChange=\{\(e\) => \{ const at = e\?\.nativeEvent\?\.selection setField\(\(f\) => selectionMoved\(f, at, shownText\(f, bpm\)\)\) \}\}/,
      /onChangeText=\{\(t\) => \{ setField\(\(f\) => typedInto\(f, t\)\)/,
      /keyboardType="number-pad"/
    ]) {
      assert.match(input, prop, `the tempo field has lost ${prop}`)
    }
    /* The net under autoFocus, once the Modal is up: Android always asks again; a focused iPhone field is only re-selected, never re-focused. */
    assert.match(flat, /<Modal visible=\{!!open\} transparent animationType="fade" onRequestClose=\{onClose\} onShow=\{shown\}/)
    assert.match(flat, /if \(Platform\.OS === 'android' \|\| !f\.isFocused\?\.\(\)\) f\.focus\(\) if \(field\.held && typed && f\.setSelection\) \{ f\.setSelection\(0, typed\.length\) setField\(selectedByHand\) \}/, 'the box selects the number once it is up without noting it did, so an iPhone snaps every tap back')
    /* Tapping the panel only brings the field back when it has lost focus: asking a focused field again selects what was typed. */
    assert.match(flat, /onPress=\{\(\) => \{ if \(!input\.current\?\.isFocused\?\.\(\)\) input\.current\?\.focus\(\) \}\}/)
    /* And it still sends what is in the box, by the shared rule. */
    assert.match(flat, /const checked = checkBpm\(typed, range\)/)
    /*
     * The same height whatever it has to say. What went wrong was a note of its
     * own above Cancel and Set, two lines taller the moment it appeared, and on
     * a 320 by 568 phone that put the metronome under the number pad.
     */
    assert.match(flat, /\{error \|\| `\$\{range\.min\} to \$\{range\.max\} beats per minute`\}/, 'the tempo error is no longer in the range line’s place')
    assert.doesNotMatch(code, /<Note\b/, 'the tempo box has a note of its own again, which makes it taller as it appears')
    assert.match(flat, /const tight = height <= 640/, 'a 360 by 640 phone is no longer counted small')
  })

  test('the tempo box has the volume pop-up’s own metronome switch, under Set, and pressing it can never set the tempo', () => {
    /* "Also, can we add the metronome on and off to this screen as well so they can quickly turn the metronome on and off?" */
    const box = withoutComments(read('mobile/src/components/TempoBox.js')).replace(/\s+/g, ' ')
    assert.match(box, /import MetronomeSwitch from '\.\/MetronomeSwitch'/, 'the tempo box has its own metronome switch rather than the volume pop-up’s')
    const tags = box.match(/<MetronomeSwitch[^>]*\/>/g) || []
    assert.deepEqual(tags, ['<MetronomeSwitch compact lines={tight ? 2 : undefined} />'], 'the tempo box has no metronome switch, or hands it something that could set the tempo')
    /* No second way of writing the metronome in the box: the switch is the only one. */
    assert.doesNotMatch(box, /setMetronome|useMetronome/, 'the tempo box writes the metronome itself')
    /* Under Cancel and Set, inside the panel that swallows presses, so it neither closes the box nor sits above Set. */
    const set = box.indexOf('<Press grow label="Set" tone="signal" on onPress={commit} />')
    const sw = box.indexOf('<MetronomeSwitch')
    assert.ok(set > 0 && sw > set, 'the switch is not under Cancel and Set')
    assert.equal(box.indexOf('</Pressable>', sw), box.indexOf('</Pressable> </View> </BlurView>'), 'the switch is outside the panel, where a press closes the box')
    /* commit is reached by Set and by the keyboard's own Done, and by nothing else. */
    assert.equal((box.match(/\bcommit\b/g) || []).length, 3, 'something other than Set and Done can send the typed tempo')
    assert.match(box, /onSubmitEditing=\{commit\}/)
    /* The switch itself knows nothing of a tempo being typed: nothing it presses reaches a write of one. */
    const sw2 = withoutComments(read('mobile/src/components/MetronomeSwitch.js'))
    assert.doesNotMatch(sw2, /\bonSet\b|\bcommit\b|\bonClose\b|setTempo|writeTempo/, 'the metronome switch can reach the tempo box’s write')
    const flatSw = sw2.replace(/\s+/g, ' ')
    assert.match(flatSw, /export default function MetronomeSwitch\(\{ compact = false, lines \}\)/)
    /* The box leaves off the heading; the line about where the click is stays, held to `lines` there. */
    assert.match(flatSw, /\{!compact \? \( <View/)
    assert.match(flatSw, /<Text numberOfLines=\{compact \? lines : undefined\} style=\{\{ color: color\.silkDim, fontSize: font\.small, paddingHorizontal: space\.sm \}\}> \{line\} <\/Text>/)
    /* "The unit didn't take it" in the line's place in the box, never cut short, and as a note of its own only in the volume pop-up. */
    assert.match(flatSw, /\{compact && said \? \( <Text accessibilityLiveRegion="polite" style=\{\{ color: color\.fault, fontSize: font\.small, paddingHorizontal: space\.sm \}\}> \{said\} <\/Text> \) : \(/, 'in the tempo box the switch’s fault comes in under its line again, under the number pad')
    assert.match(flatSw, /\{!compact && said \? \( <Note tone="fault"/)
    /* And the volume pop-up's is as it was, with its heading. */
    assert.match(read('mobile/src/components/Volume.js'), /<MetronomeSwitch \/>/)
  })

  test('the browser’s tempo box selects the tempo as it opens and has the Volume sheet’s metronome switch', () => {
    const tap = withoutComments(read('src/components/TapTempo.jsx')).replace(/\s+/g, ' ')
    const group = tap.slice(tap.indexOf('<div className="gig-tempo"'), tap.indexOf('</div> ) : null}', tap.indexOf('<div className="gig-tempo"')))
    assert.match(tap, /import MetronomeSwitch from '\.\/MetronomeSwitch'/)
    assert.match(group, /<MetronomeSwitch slug=\{currentDeviceSlug\(\)\} heading=\{false\} \/>/, 'the browser’s tempo box has no metronome switch')
    assert.ok(group.indexOf('<MetronomeSwitch') > group.indexOf('<BpmBox'), 'the switch is above the tempo')
    /*
     * A press on the switch keeps focus on the field, and the field's blur is
     * told it was the box's own — by lib/boxPress.js, the guard the tests
     * below run, new each time the box opens and handed to the box and the
     * field as it is.
     */
    assert.match(tap, /import \{ boxPresses \} from '\.\.\/lib\/boxPress'/)
    assert.match(
      tap,
      /const presses = useRef\(null\) if \(!typing\) presses\.current = null else if \(!presses\.current\) presses\.current = boxPresses\('\.gig-tempo'\) const \{ handlers: inBox, keepOpen \} = presses\.current \?\? \{\}/,
      'the tempo box’s press guard is not the one the tests run, or a press from its last opening can hold it open'
    )
    assert.match(group, /^<div className="gig-tempo" role="group" aria-label="Type a tempo" \{\.\.\.inBox\}>/)
    assert.match(group, /<BpmBox bpm=\{bpm\} autoFocus onSet=\{typeTempo\} .*?keepOpen=\{keepOpen\} \/>/)
    /*
     * Nothing in the box but the field's Enter or blur sets the tempo or shuts
     * the box: no press of its own on anything in it (the switch's wrapper
     * included), no other set of handlers spread over it, and typeTempo and
     * setTyping reached only through BpmBox's onSet and onDone.
     */
    assert.deepEqual(group.match(/\bon[A-Z]\w*=/g), ['onSet=', 'onError=', 'onDone='], 'something in the tempo box has a press of its own, which can reach the tempo')
    assert.deepEqual(group.match(/\{\.\.\.\w+\}/g), ['{...inBox}'], 'the tempo box takes handlers other than the press guard')
    assert.deepEqual(group.match(/\btypeTempo\b|\bsetTyping\b/g), ['typeTempo', 'setTyping'])
    assert.match(group, /onDone=\{\(\) => setTyping\(false\)\}/)
    assert.equal((tap.match(/\btypeTempo\b/g) || []).length, 2, 'the typed tempo is sent from somewhere other than the field')
    /* The guard is handed nothing it could call, and imports nothing that could. */
    const guard = withoutComments(read('src/lib/boxPress.js'))
    assert.doesNotMatch(guard, /^\s*import\b/m, 'the tempo box’s press guard imports something')
    assert.match(guard.replace(/\s+/g, ' '), /^ ?export function boxPresses\(group\) \{/)
    assert.doesNotMatch(guard, /typeTempo|setTyping|setTempo|onSet|onDone|commit/, 'the tempo box’s press guard can reach the tempo')
    const browserSwitch = withoutComments(read('src/components/MetronomeSwitch.jsx'))
    assert.doesNotMatch(browserSwitch, /onSet|typeTempo|setTyping|setTempo/)
    assert.match(browserSwitch.replace(/\s+/g, ' '), /export default function MetronomeSwitch\(\{ slug, heading = true \}\)/)
    /* The Volume sheet's is as it was. */
    assert.match(read('src/App.jsx'), /<MetronomeSwitch slug=\{slugOfUnit\(device\)\} \/>/)
    /* The field: the number from its first render, selected on focus with setSelectionRange (Safari on an iPhone), kept selected through the press that focused it. */
    const bpmBox = withoutComments(read('src/components/BpmBox.jsx')).replace(/\s+/g, ' ')
    assert.match(bpmBox, /useState\(autoFocus && Number\.isFinite\(bpm\) \? String\(Math\.round\(bpm\)\) : null\)/, 'the box opens empty and the tempo arrives after the cursor')
    assert.match(bpmBox, /autoFocus=\{autoFocus\}/)
    assert.match(bpmBox, /requestAnimationFrame\(\(\) => selectAll\(el\)\)/, 'the box does not select the tempo as it opens')
    assert.match(bpmBox, /el\.setSelectionRange\(0, el\.value\.length\)/)
    assert.match(bpmBox, /onMouseUp=\{\(e\) => \{ if \(!pressFocus\.current && !fresh\.current\) return pressFocus\.current = false e\.preventDefault\(\)/, 'the first press into an already-focused field puts the cursor at the finger again')
    assert.match(bpmBox, /const fresh = useRef\(autoFocus\)/)
    assert.match(bpmBox, /if \(!entered\.current && !abandon\.current && keepOpen\?\.\(e\)\) return/, 'Enter or Escape can be held up by the box staying open')
  })

  test('the browser’s tempo box, run: open selected, a press on the switch neither sends nor closes, Enter still sets', async () => {
    const { transformSync } = await import('esbuild')
    const dir = mkdtempSync(join(tmpdir(), 'bpm-box-'))
    try {
      /* A React that keeps hook state by call order and redraws when asked. */
      writeFileSync(join(dir, 'package.json'), '{ "type": "module" }')
      writeFileSync(
        join(dir, 'react.mjs'),
        `export const h = (type, props, ...children) => ({ type, props: props || {}, children })
         const slots = []
         let at = 0
         export const begin = () => { at = 0 }
         export const remount = () => { slots.length = 0 }
         export function useState(initial) {
           const i = at++
           if (!(i in slots)) slots[i] = typeof initial === 'function' ? initial() : initial
           return [slots[i], (v) => { slots[i] = typeof v === 'function' ? v(slots[i]) : v }]
         }
         export function useRef(current = null) {
           const i = at++
           if (!(i in slots)) slots[i] = { current }
           return slots[i]
         }`
      )
      let src = transformSync(read('src/components/BpmBox.jsx'), { loader: 'jsx', jsx: 'transform', jsxFactory: 'h', format: 'esm' }).code
      src = src.replaceAll('from "react"', "from './react.mjs'").replaceAll('from "../../shared/tempo.mjs"', `from '${pathToFileURL(fileURLToPath(new URL('../shared/tempo.mjs', import.meta.url))).href}'`)
      writeFileSync(join(dir, 'BpmBox.mjs'), "import { h } from './react.mjs'\n" + src)
      const react = await import(pathToFileURL(join(dir, 'react.mjs')).href)
      const { default: BpmBox } = await import(pathToFileURL(join(dir, 'BpmBox.mjs')).href)
      /* TapTempo's own guard, not a stand-in for it, handed to the field as TapTempo hands it. */
      const { boxPresses } = await import('../src/lib/boxPress.js')
      let presses = boxPresses('.gig-tempo')
      const sets = []
      let done = 0
      const props = { bpm: 120, autoFocus: true, range: { min: 24, max: 250 }, onSet: (n) => sets.push(n), onDone: () => done++, onError: () => {}, keepOpen: presses.keepOpen }
      const draw = () => {
        react.begin()
        return BpmBox(props)
      }
      /* Opened: the tempo is in it before anything else happens. */
      assert.equal(draw().props.value, '120', 'the box opened without the tempo in it')
      /* Focused: all of it selected, once the frame is drawn. */
      const el = { value: '120', setSelectionRange(a, b) { this.sel = [a, b] } }
      const frames = []
      globalThis.document = { activeElement: el }
      globalThis.requestAnimationFrame = (fn) => frames.push(fn)
      draw().props.onFocus({ target: el })
      frames.splice(0).forEach((fn) => fn())
      assert.deepEqual(el.sel, [0, 3], 'the box opened with the tempo not selected')
      /*
       * An iPhone: the hold's timer focused the field, with no keyboard, so the
       * player taps a field that already has focus. No focus event, and the
       * caret goes to the finger after the press — unless the number is
       * selected again, on the let-go and once more just after it.
       */
      const tick = () => new Promise((ok) => setTimeout(ok, 5))
      let stopped = false
      draw().props.onMouseDown({ currentTarget: el })
      el.sel = [3, 3]
      draw().props.onMouseUp({ currentTarget: el, preventDefault: () => (stopped = true) })
      assert.ok(stopped, 'the first tap into a field that already had focus put the cursor at the finger')
      assert.deepEqual(el.sel, [0, 3], 'the first tap into a field that already had focus left the tempo unselected')
      el.sel = [3, 3]
      await tick()
      assert.deepEqual(el.sel, [0, 3], 'the caret an iPhone places after the tap was left there')
      /* Only the first: the next press is somebody putting the cursor somewhere, and it stays there. */
      stopped = false
      el.sel = [1, 1]
      draw().props.onMouseDown({ currentTarget: el })
      draw().props.onMouseUp({ currentTarget: el, preventDefault: () => (stopped = true) })
      await tick()
      assert.ok(!stopped, 'a second press into the field can never place the cursor')
      assert.deepEqual(el.sel, [1, 1])
      /* A press focusing the field: its let-go is kept from moving the cursor. */
      globalThis.document.activeElement = null
      draw().props.onMouseDown({ currentTarget: el })
      globalThis.document.activeElement = el
      el.sel = null
      draw().props.onMouseUp({ currentTarget: el, preventDefault: () => (stopped = true) })
      assert.ok(stopped, 'letting go of the press that focused the field moves the cursor off the selection')
      assert.deepEqual(el.sel, [0, 3])
      /*
       * 132 typed, then the metronome pressed, the way an iPhone does it: the
       * press goes down on the switch, the field loses focus with nothing to
       * hand it to, and only then does the switch's click land.
       */
      draw().props.onChange({ target: { value: '132' } })
      el.closest = (sel) => (sel === '.gig-tempo' ? { contains: () => false } : null)
      const sw = { tagName: 'BUTTON' }
      presses.handlers.onPointerDown({ target: sw })
      presses.handlers.onMouseDown({ target: sw, preventDefault: () => {} })
      draw().props.onBlur({ relatedTarget: null, currentTarget: el })
      assert.deepEqual(sets, [], 'pressing the metronome sent the typed tempo')
      assert.equal(done, 0, 'pressing the metronome closed the box')
      assert.equal(draw().props.value, '132', 'pressing the metronome lost what was typed')
      presses.handlers.onClickCapture()
      await tick()
      /* A blur after that click — the keyboard's Done — sets it as it always did. */
      draw().props.onBlur({ relatedTarget: null, currentTarget: el })
      assert.deepEqual(sets, [132], 'after the metronome was pressed, the keyboard’s Done no longer sets the typed tempo')
      assert.equal(done, 1)
      /* Opened again, 140 typed, a press on the switch still down: Enter sets it, whatever the box says about staying open. */
      react.remount()
      presses = boxPresses('.gig-tempo')
      props.keepOpen = presses.keepOpen
      draw().props.onChange({ target: { value: '140' } })
      presses.handlers.onPointerDown({ target: sw })
      assert.equal(presses.keepOpen({ relatedTarget: null, currentTarget: el }), true)
      const input = draw()
      input.props.onKeyDown({ key: 'Enter', currentTarget: { blur: () => draw().props.onBlur({ relatedTarget: null, currentTarget: el }) } })
      assert.deepEqual(sets, [132, 140], 'Enter did not set the typed tempo')
      assert.equal(done, 2)
      /* Opened again and typed into straight away: the cursor is the player's from the first key, so a press then moves it. */
      react.remount()
      draw().props.onChange({ target: { value: '9' } })
      stopped = false
      el.sel = [0, 0]
      draw().props.onMouseDown({ currentTarget: el })
      draw().props.onMouseUp({ currentTarget: el, preventDefault: () => (stopped = true) })
      await tick()
      assert.ok(!stopped, 'a press after typing selects everything typed again')
      assert.deepEqual(el.sel, [0, 0])
    } finally {
      delete globalThis.document
      delete globalThis.requestAnimationFrame
      rmSync(dir, { recursive: true, force: true })
    }
  })

  test('the browser’s tempo box, its press guard run: a press on the switch holds the field’s blur, and only until its click is done', async () => {
    const { boxPresses } = await import('../src/lib/boxPress.js')
    const tick = () => new Promise((ok) => setTimeout(ok, 5))
    const button = { tagName: 'BUTTON' }
    const field = { tagName: 'INPUT' }
    const inBox = { tagName: 'BUTTON' }
    const elsewhere = { tagName: 'BUTTON' }
    const asked = []
    const input = { tagName: 'INPUT', closest: (sel) => (asked.push(sel), sel === '.gig-tempo' ? { contains: (n) => n === inBox } : null) }
    const blur = (relatedTarget = null) => ({ relatedTarget, currentTarget: input })
    const { handlers, keepOpen } = boxPresses('.gig-tempo')
    /* Nothing pressed: a blur with nowhere for focus to go sets, as it always did. */
    assert.equal(keepOpen(blur()), false, 'the field’s blur no longer sets the typed tempo')
    /* The switch pressed: its mouse-down keeps focus on the field, and a blur before its click is the box's own. */
    let stopped = false
    handlers.onPointerDown({ target: button })
    handlers.onMouseDown({ target: button, preventDefault: () => (stopped = true) })
    assert.ok(stopped, 'a press on the metronome takes focus off the field, which sends the typed tempo')
    assert.equal(keepOpen(blur()), true, 'a press on the metronome sent the typed tempo and shut the box (an iPhone)')
    /* Its click lands, and the press is over just after it; then a blur is judged on its own. */
    handlers.onClickCapture()
    assert.equal(keepOpen(blur()), true, 'a press on the metronome was over before its own click had done its work')
    await tick()
    assert.equal(keepOpen(blur()), false, 'after a press on the metronome, the keyboard’s Done no longer sets the typed tempo')
    /* A press on the field itself is the field's: its mouse-down is left alone, and a blur after it sets. */
    stopped = false
    handlers.onPointerDown({ target: field })
    handlers.onMouseDown({ target: field, preventDefault: () => (stopped = true) })
    assert.ok(!stopped, 'a press on the field cannot put the cursor where the finger is')
    assert.equal(keepOpen(blur()), false)
    /* A press that turned into a scroll, and a key: over, with no click coming to end them. */
    handlers.onPointerDown({ target: button })
    handlers.onPointerCancel()
    assert.equal(keepOpen(blur()), false, 'a scroll that began on the box kept the keyboard’s Done from setting the tempo')
    handlers.onPointerDown({ target: button })
    handlers.onKeyDown()
    assert.equal(keepOpen(blur()), false, 'a key after a press on the box kept the field’s blur from setting the tempo')
    /* Focus moved by Tab onto something in the box stays in the box; anywhere else, it sets. */
    assert.equal(keepOpen(blur(inBox)), true)
    assert.equal(keepOpen(blur(elsewhere)), false)
    assert.deepEqual([...new Set(asked)], ['.gig-tempo'])
    /* Each opening its own: a press left over from the last does not hold the next open. */
    handlers.onPointerDown({ target: button })
    assert.equal(boxPresses('.gig-tempo').keepOpen(blur()), false, 'a press from the last time the box was open holds this one open')
  })

  test('the green light on Tap lights on the phone’s own click while it clicks, and keeps counted time when it does not', async () => {
    /* Run, not read: TempoDot beside stand-ins for React, Animated, the phone's beat and a clock the test turns. */
    const dir = mkdtempSync(join(tmpdir(), 'dot-'))
    try {
      const files = {
        'package.json': '{ "type": "module" }',
        'react.js': 'export const useEffect = (fn) => { globalThis.__dotEffect = fn }\nexport const useRef = (v) => ({ current: v })\n',
        'clock.js': `
          let t = 0
          let seq = 0
          const timers = new Map()
          export const now = () => t
          export function setTimeout(fn, ms = 0) { const id = ++seq; timers.set(id, { id, at: t + ms, fn }); return id }
          export function clearTimeout(id) { timers.delete(id) }
          export function advance(ms) {
            const end = t + ms
            for (;;) {
              let next = null
              for (const x of timers.values()) if (x.at <= end && (!next || x.at < next.at)) next = x
              if (!next) break
              timers.delete(next.id)
              t = next.at
              next.fn()
            }
            t = end
          }
          /* A timer that fires late, as one on a phone does now and then. */
          export const lateBy = (ms) => { for (const x of timers.values()) x.at += ms }
        `,
        'rn.js': `
          import { now } from './clock.js'
          export const lit = []
          class Value { constructor(v) { this.v = v } setValue(v) { this.v = v; if (v === 1) lit.push(now()) } }
          export const Animated = { Value, View: 'View', timing: () => ({ start() {} }) }
          export const Easing = { out: (f) => f, quad: (x) => x }
        `,
        'metronome.js': `
          const fns = new Set()
          export let clicking = false
          export const __clicking = (on) => { clicking = on }
          export const usePhoneClicking = () => clicking
          export const onPhoneBeat = (fn) => (fns.add(fn), () => fns.delete(fn))
          export const __beat = () => fns.forEach((fn) => fn())
        `,
        'metronome-rules.js': read('mobile/src/lib/metronome-rules.js'),
        'device-word.js': read('mobile/src/lib/device-word.js'),
    'device-word.js': read('mobile/src/lib/device-word.js'),
        'theme.js': "export const color = { ok: 'green' }\n",
        'TempoDot.js': ("import * as __clock from './clock.js'\n" + read('mobile/src/components/TempoDot.js'))
          .replace(/\bsetTimeout\(/g, '__clock.setTimeout(')
          .replace(/\bclearTimeout\(/g, '__clock.clearTimeout(')
          .replace(/\bDate\.now\(\)/g, '__clock.now()')
          .replace("from 'react'", "from './react.js'")
          .replace("from 'react-native'", "from './rn.js'")
          .replace("from '../lib/metronome'", "from './metronome.js'")
          .replace("from '../lib/metronome-rules'", "from './metronome-rules.js'")
          .replace("from '../lib/theme'", "from './theme.js'")
          /* What it draws is JSX, which Node does not read; what is under test is when it lights. */
          .replace(/\n  if \(!beat\) return null\n  return \([\s\S]*?\n  \)\n\}/, '\n  return null\n}')
      }
      assert.doesNotMatch(files['TempoDot.js'], /<Animated/, 'the bench could not take the drawing out of TempoDot')
      for (const [name, text] of Object.entries(files)) writeFileSync(join(dir, name), text)
      const at = (f) => pathToFileURL(join(dir, f)).href
      const { default: TempoDot } = await import(at('TempoDot.js'))
      const clock = await import(at('clock.js'))
      const rn = await import(at('rn.js'))
      const beat = await import(at('metronome.js'))

      /* Not clicking: counted from the start, so a late timer is late once and the beats after it are not. */
      TempoDot({ bpm: 120 })
      const stop = globalThis.__dotEffect()
      clock.advance(1000)
      clock.lateBy(30)
      clock.advance(14000)
      assert.deepEqual(rn.lit.slice(0, 4), [0, 500, 1000, 1530])
      assert.deepEqual(rn.lit.slice(4, 8), [2000, 2500, 3000, 3500], 'one late beat drags every beat after it')
      assert.equal(rn.lit.at(-1), 15000, 'the light drifts off the tempo')
      assert.equal(rn.lit.length, 31)
      stop()
      clock.advance(5000)
      assert.equal(rn.lit.length, 31, 'the light keeps flashing after it is gone')

      /* Clicking: it lights on the phone's own beat, and only then. */
      rn.lit.length = 0
      beat.__clicking(true)
      TempoDot({ bpm: 120 })
      const unhook = globalThis.__dotEffect()
      clock.advance(2000)
      assert.equal(rn.lit.length, 0, 'the light keeps a clock of its own beside the phone’s click')
      beat.__beat()
      beat.__beat()
      assert.equal(rn.lit.length, 2, 'the light does not light on the phone’s click')
      unhook()
      beat.__beat()
      assert.equal(rn.lit.length, 2)
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
    const metronome = read('mobile/src/lib/metronome.js').replace(/\s+/g, ' ')
    assert.match(metronome, /tick\(\) onBeat\?\.\(\) for \(const fn of beatWatchers\) fn\(\)/, 'the light, the flash and the tap are not on the same beat')
  })

  test('the browser flashes on the beep as it is heard, and takes back beeps not yet heard when it stops', () => {
    const src = read('src/lib/metronome.js').replace(/\s+/g, ' ')
    assert.match(src, /const heard = heardAt\(ctx, next\)/, 'the flash is timed to when the beep is made, not heard')
    assert.match(src, /Math\.max\(0, heard - FLASH_FRAME_MS - performance\.now\(\)\)/)
    assert.match(src, /ctx\.getOutputTimestamp\?\.\(\)/)
    assert.match(src, /\(ctx\.baseLatency \|\| 0\) \+ \(ctx\.outputLatency \|\| 0\)/)
    assert.match(src, /for \(const b of booked\) \{ try \{ b\.osc\.stop\(\) \}/, 'a beep booked before a stop sounds with no flash')
    assert.match(src, /for \(const t of flashes\) clearTimeout\(t\)/)
    assert.match(src, /if \(ctx && ctx\.state === 'running'\)/, 'beeps are booked on a clock that is not running')
    /* Audio that stops mid-run takes back what was booked on its frozen clock, or it doubles when it comes back. */
    assert.match(withoutComments(read('src/lib/metronome.js')).replace(/\s+/g, ' '), /if \(silentSince === null\) \{ takeBack\(\) silentSince = ctx \? now : now - beat \}/, 'beeps booked before the audio stopped sound beside the new ones')
    assert.match(read('src/styles.css'), /\.metronome-beat \{[\s\S]{0,700}will-change: opacity;/)
  })

  test('the metronome clicks where it is told, with each unit’s own switch', async () => {
    const m = await import('../shared/metronome.mjs')
    /* Off unless turned on, and on the unit unless told otherwise. */
    assert.deepEqual(m.metronomeSetting(null), { on: false, where: 'unit', watch: false })
    assert.deepEqual(m.metronomeSetting({ on: true, where: 'nowhere' }), { on: true, where: 'unit', watch: false })
    assert.deepEqual(m.clicks({ on: true, where: 'unit' }), { unit: true, phone: false, watch: false })
    assert.deepEqual(m.clicks({ on: true, where: 'unit', watch: true }), { unit: true, phone: false, watch: true })
    assert.deepEqual(m.clicks({ on: true, where: 'phone' }), { unit: false, phone: true, watch: false })
    assert.deepEqual(m.clicks({ on: true, where: 'both' }), { unit: true, phone: true, watch: false })
    assert.deepEqual(m.clicks({ on: false, where: 'both', watch: true }), { unit: false, phone: false, watch: false })

    /* Each unit's own number — one unit's sent to another would mis-address. */
    assert.deepEqual(m.unitMetronomeRequest('fm3', true), { method: 'PUT', path: '/preset/blocks/1/params/14878', body: { value: 1, continuous: false } })
    assert.deepEqual(m.unitMetronomeRequest('fm9', false), { method: 'PUT', path: '/preset/blocks/1/params/14907', body: { value: 0, continuous: false } })
    assert.deepEqual(m.unitMetronomeRequest('axefxiii', true).path, '/preset/blocks/1/params/14655')
    /* Never a guess at an AM4's global settings: that froze his AM4 on SAVING. */
    assert.equal(m.unitMetronomeRequest('am4', true), null, 'the AM4 is written an unproven global')
    assert.equal(m.unitMetronomeRequest('am4', false), null)
    assert.equal(m.unitMetronomeRequest('vp4', true), null, 'a unit with no known switch is written a guess')
    /* The codec agrees about those numbers. */
    const codec = '../../forgefx-midi/src/gen3'
    for (const [unit, id] of [['fm3', 14878], ['fm9', 14907], ['axe-fx-iii', 14655]]) {
      const path = new URL(`${codec}/${unit}/params.ts`, import.meta.url)
      if (existsSync(path)) assert.match(readFileSync(path, 'utf8'), new RegExp(`paramId: ${id}, name: 'GLOBAL_METRONOME'`), `${unit}'s metronome is not ${id}`)
    }
    /* Every relay request it makes is one the computer allows from a phone. */
    const { hostAllows } = await import('../shared/relay-rules.mjs')
    for (const slug of ['fm3', 'fm9', 'axefxiii']) {
      const r = m.unitMetronomeRequest(slug, true)
      assert.ok(hostAllows(r.method, r.path), `the computer refuses ${slug}'s metronome from a phone`)
    }

    /* Beats counted from the start, so one late timer does not drag the rest. */
    assert.equal(m.beatMs(120), 500)
    assert.equal(m.beatMs(10), null)
    assert.equal(m.nextBeat(0, 1250, 500), 1500)
    assert.equal(m.nextBeat(0, 1500, 500), 2000)
    /* A timer a moment early is still that beat: not booked again a few milliseconds later. */
    assert.equal(m.nextBeat(0, 923, 60000 / 130), 3 * (60000 / 130), 'a beat a fraction of a millisecond early is played twice')
    assert.equal(m.nextBeat(0, 1497, 500), 2000, 'an Android timer three milliseconds early plays the beat twice')
    assert.equal(m.nextBeat(0, 1489, 500), 1500)
    /* The flash waits for the click by this phone's usual delay, and Flash timing moves it within bounds. */
    assert.equal(m.flashLead('ios'), 40)
    assert.equal(m.flashLead('android'), 100)
    assert.equal(m.flashLead('web'), 0)
    assert.equal(m.flashLead('ios', 60), 100)
    assert.equal(m.flashLead('ios', -1000), 0, 'the flash is booked before the beat')
    assert.equal(m.flashNudge(37), 40)
    assert.equal(m.flashNudge(1000), 400)
    assert.equal(m.flashNudge('nonsense'), 0)
    assert.equal(m.flashTimingNote(0), 'Standard')
    assert.equal(m.flashTimingNote(60), '60 ms later than standard')
    assert.equal(m.flashTimingNote(-20), '20 ms earlier than standard')
    /* As early as it goes is the flash on the click: no press past that moves nothing under a line saying it did. */
    assert.equal(m.nudgeFloor('ios'), -40)
    assert.equal(m.nudgeFloor('android'), -100)
    assert.equal(m.flashNudge(-100, 'ios'), -40, 'Earlier goes on past where the flash can move on an iPhone')
    assert.equal(m.flashTimingNote(-100, 'ios'), '40 ms earlier than standard')
    assert.equal(m.flashLead('ios', -40), 0)
    assert.match(read('mobile/src/screens/Settings.js'), /disabled=\{flashTiming <= nudgeFloor\(Platform\.OS\)\}/, 'Earlier stays live where it moves nothing')
    assert.match(read('mobile/src/lib/metronome.js'), /nudge = flashNudge\(ms, Platform\.OS\)/)
    assert.match(m.metronomeNote({ on: true, where: 'unit' }, 'fm3', 120), /On, 120 BPM, on the unit/)
    assert.match(m.metronomeNote({ on: true, where: 'unit' }, 'vp4', 120), /no metronome the app can switch/)
    assert.equal(m.metronomeNote({ on: false }, 'fm3', 120), 'Off')

    /* Both ends: a row on Settings, the unit told only when its half changes, never in the demo. */
    const phone = read('mobile/src/lib/metronome.js')
    assert.match(phone, /if \(before === after\) return \{ ok: true \}/, 'turning the phone’s click on switches the unit’s off')
    assert.match(read('mobile/src/lib/device.js'), /if \(!ask \|\| demoDevice\(\)\) return/)
    assert.match(read('src/lib/forgefx.js'), /if \(!ask \|\| mock\) return/)
    assert.match(read('mobile/src/screens/Settings.js'), /page === 'metronome'/)
    assert.match(read('src/App.jsx'), /setupPage === 'metronome'/)
    assert.match(read('mobile/App.js'), /<MetronomeBeat bpm=\{rigBpm\} \/>/)
    assert.match(read('src/App.jsx'), /<MetronomeBeat bpm=\{rigBpm\} \/>/)
    /* The beat never takes a press away from the screen under it. */
    assert.match(read('mobile/src/components/MetronomeBeat.js'), /pointerEvents="none"/)
    /*
     * And it is rounded with the glass. "The corners of the screen get cut
     * off where they're rounded": a square frame to the very edge puts its
     * corners behind the screen's curve.
     */
    const beat = read('mobile/src/components/MetronomeBeat.js')
    assert.match(beat, /borderRadius: round/, 'the beat’s frame is square again, and its corners are cut off by the screen')
    assert.match(beat, /const round = cornerRadius\(\{ os: Platform\.OS, width, height, top, bottom, pad: Platform\.isPad \}\)/)
    assert.match(beat, /borderCurve: 'continuous'/, 'the frame bends later than the iPhone’s glass does, and its corners are clipped')
    const { cornerRadius } = await import('../mobile/src/lib/screenCorners.js')
    /* His iPhone 17 Pro Max, and its family. */
    assert.equal(cornerRadius({ os: 'ios', width: 440, height: 956, top: 62, bottom: 34 }), 62)
    assert.equal(cornerRadius({ os: 'ios', width: 956, height: 440, top: 62, bottom: 34 }), 62, 'a screen read the other way up is another phone')
    assert.equal(cornerRadius({ os: 'ios', width: 393, height: 852, top: 59, bottom: 34 }), 55)
    assert.equal(cornerRadius({ os: 'ios', width: 420, height: 912, top: 68, bottom: 34 }), 62)
    /* A size two models share takes the rounder: a frame that curves more than the glass is all seen. */
    assert.equal(cornerRadius({ os: 'ios', width: 375, height: 812, top: 44, bottom: 34 }), 44)
    assert.equal(cornerRadius({ os: 'ios', width: 375, height: 812, top: 50, bottom: 34 }), 44)
    /* Display Zoom: a big phone zoomed says it is an X, and its glass is far rounder than an X's. */
    assert.ok(cornerRadius({ os: 'ios', width: 375, height: 812, top: 53, bottom: 34 }) >= 56, 'a zoomed big iPhone has its corners cut off again')
    /* An iPhone not on the list yet is treated as the roundest; one with a home button is square. */
    assert.equal(cornerRadius({ os: 'ios', width: 999, height: 2000, top: 62, bottom: 34 }), 62)
    assert.equal(cornerRadius({ os: 'ios', width: 375, height: 667, top: 20, bottom: 0 }), 0)
    /* Rounded iPads have a 24-point status bar, which the first version took for square glass. */
    assert.equal(cornerRadius({ os: 'ios', width: 1024, height: 1366, top: 24, bottom: 20, pad: true }), 22, 'a rounded iPad gets a square flash')
    assert.equal(cornerRadius({ os: 'ios', width: 1024, height: 1366, top: 20, bottom: 0, pad: true }), 0, 'an iPad with a home button gets round corners')
    /* Android cannot be asked without native code: rounder than Google's own (a Pixel 9 is 50), capped for tablets. */
    assert.ok(cornerRadius({ os: 'android', width: 411, height: 915 }) >= 51, 'a Pixel 9’s corners are cut off')
    assert.equal(cornerRadius({ os: 'android', width: 800, height: 1280 }), 60)
    assert.equal(cornerRadius({}), 0)
    /* And the browser opened from the home screen, which reaches under the glass too. */
    assert.match(read('src/styles.css'), /\.metronome-beat \{[^}]*border-radius: clamp\(0px, calc\(env\(safe-area-inset-bottom, 0px\) \* 1000\), 62px\)/)
    assert.match(read('src/styles.css'), /\.metronome-beat \{[^}]*pointer-events: none/)
  })

  test('the phone stays awake while its own click is running, on every screen', () => {
    /*
     * The screen only stayed on while Play or Edit was open (useKeepAwake in
     * Stage and Edit). The click runs everywhere — MetronomeBeat is drawn over
     * the whole app — so on the setlist or the preset list the phone locked
     * itself on its usual timeout and the click stopped with it.
     */
    const beat = read('mobile/src/components/MetronomeBeat.js')
    assert.match(beat, /import \{ useKeepAwake \} from 'expo-keep-awake'/, 'the beat does not use the keep-awake the Play screen uses')
    assert.match(beat, /const clicking = usePhoneClick\(bpm, onBeat\)/, 'the beat does not ask whether the phone is clicking')
    assert.match(beat, /\{clicking \? <StayAwake \/> : null\}/, 'the screen is held awake whether or not the click is running')
    /* Its own tag: a bare one would be fine today, but a shared default tag
       would let the metronome letting go release Play's hold too. */
    assert.match(beat, /function StayAwake\(\) \{\s*useKeepAwake\('metronome'\)\s*return null\s*\}/, 'the metronome holds the screen under no tag of its own')

    /* "Running" is exactly when the click ticks: switched on for the phone, and a tempo to click at. */
    const lib = read('mobile/src/lib/metronome.js')
    const hook = lib.slice(lib.indexOf('export function usePhoneClick'))
    assert.match(hook, /const running = Boolean\(on && beat\)/, 'the phone is kept awake on something other than the click running')
    assert.match(hook, /if \(!on \|\| !beat\) return undefined/, 'the click and the keep-awake no longer start on the same thing')
    assert.match(hook, /\}, \[on, beat, onBeat\]\)\s*return running\s*\}/, 'usePhoneClick no longer says whether it is clicking')

    /* No new package: the one the Play screen already uses, so nothing native moves. */
    assert.ok(JSON.parse(read('mobile/package.json')).dependencies['expo-keep-awake'], 'expo-keep-awake is gone from the phone')
    /* And Play and Edit keep their own holds as before. */
    assert.match(read('mobile/src/screens/Stage.js'), /useKeepAwake\(\)/)
    assert.match(read('mobile/src/screens/Edit.js'), /useKeepAwake\(\)/)
  })

