    assert.equal(asked(CHAIN), 1)
    assert.equal(asked(SUMMARY), 0, 'an empty slot was dumped for its scene names')
    assert.equal(asked(/^GET \/presets\/\d+\/scenes$/), 0)
    /* Pulling down, as somebody building in it does. */
